// Typed access to the Rust core. The bindings in ./pkg are generated by
// scripts/build-wasm.sh; the module is loaded once, on first use.
import init, * as wasm from './pkg/crusty_wasm.js'
import type { Language, WebRequest, WebResponse } from './types'

export * from './types'

let ready: Promise<unknown> | undefined
const load = () => (ready ??= init())

export async function sendRequest(request: WebRequest): Promise<WebResponse> {
  await load()
  return (await wasm.sendRequest(request)) as WebResponse
}

export async function importCurl(command: string): Promise<WebRequest> {
  await load()
  return wasm.importCurl(command) as WebRequest
}

export async function generateCode(request: WebRequest, language: string): Promise<string> {
  await load()
  return wasm.generateCode(request, language)
}

export async function languages(): Promise<Language[]> {
  await load()
  return wasm.languages() as Language[]
}

// The core throws plain strings that are ready to show.
export function errorMessage(error: unknown): string {
  if (typeof error === 'string') return error
  if (error instanceof Error) return error.message
  return String(error)
}
